def probe(u, case):
    t_max = 2.3
    T = 0.2
    delta_t = 1.5
    v = 6.3
    A = 1.0

    t = u * t_max
    d = v * delta_t / 2

    y_b = A * sin(2 * pi * t / T)

    if t < delta_t:
        y_c = 0.0
    else:
        y_c = A * sin(2 * pi * (t - delta_t) / T)

    y_sum = y_b + y_c

    half_delta_t = delta_t / 2
    if t <= half_delta_t:
        p = v * t
    elif t <= delta_t:
        p = d - v * (t - half_delta_t)
    else:
        p = 0.0

    return {"u": u, "t": t, "p": p, "d": d, "y_b": y_b, "y_c": y_c, "y_sum": y_sum}
